#include <ESP32Servo.h>

Servo servo1;
const int SERVO_PIN = 18;
bool done = false;

void setup() {
  Serial.begin(115200);
  servo1.attach(SERVO_PIN);
}

void loop() {
  if (done) return;
  for (int a = 0; a <= 180; a += 2) { servo1.write(a); delay(15); }
  for (int a = 180; a >= 0; a -= 2) { servo1.write(a); delay(15); }
  Serial.println("SWEEP");
  done = true;
}
